#!/usr/bin/env bash
# Print the three most frequent client IPs, using log order to resolve ties.
set -euo pipefail

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)

awk '
    NF {
        ip = $1
        if (!(ip in count))
            first_seen[ip] = ++sequence
        count[ip]++
    }
    END {
        for (ip in count)
            printf "%d\t%d\t%s\n", count[ip], first_seen[ip], ip
    }
' "$script_dir/access.log" \
    | sort -t $'\t' -k1,1nr -k2,2n \
    | head -n 3 \
    | cut -f3-
